import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gelu_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void gelu_kernel_vec4(const float4* __restrict__ x, float4* __restrict__ y, int n4) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n4) {
        float4 in = x[idx];
        float4 out;

        const float c = 0.7978845608028654f; // sqrt(2/pi)
        const float a = 0.044715f;

        float x0 = in.x;
        float x1 = in.y;
        float x2 = in.z;
        float x3 = in.w;

        float t0 = c * (x0 + a * x0 * x0 * x0);
        float t1 = c * (x1 + a * x1 * x1 * x1);
        float t2 = c * (x2 + a * x2 * x2 * x2);
        float t3 = c * (x3 + a * x3 * x3 * x3);

        out.x = 0.5f * x0 * (1.0f + tanhf(t0));
        out.y = 0.5f * x1 * (1.0f + tanhf(t1));
        out.z = 0.5f * x2 * (1.0f + tanhf(t2));
        out.w = 0.5f * x3 * (1.0f + tanhf(t3));

        y[idx] = out;
    }
}

__global__ void gelu_kernel_scalar(const float* __restrict__ x, float* __restrict__ y, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        float xv = x[idx];
        const float c = 0.7978845608028654f;
        const float a = 0.044715f;
        float t = c * (xv + a * xv * xv * xv);
        y[idx] = 0.5f * xv * (1.0f + tanhf(t));
    }
}

torch::Tensor gelu_cuda(torch::Tensor x) {
    auto y = torch::empty_like(x);
    int n = x.numel();

    if (n % 4 == 0) {
        int n4 = n / 4;
        const int threads = 256;
        const int blocks = (n4 + threads - 1) / threads;
        gelu_kernel_vec4<<<blocks, threads>>>(
            reinterpret_cast<const float4*>(x.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            n4
        );
    } else {
        const int threads = 256;
        const int blocks = (n + threads - 1) / threads;
        gelu_kernel_scalar<<<blocks, threads>>>(
            x.data_ptr<float>(),
            y.data_ptr<float>(),
            n
        );
    }

    return y;
}
"""

gelu_cpp_source = "torch::Tensor gelu_cuda(torch::Tensor x);"

gelu_module = load_inline(
    name="gelu_module",
    cpp_sources=gelu_cpp_source,
    cuda_sources=gelu_source,
    functions=["gelu_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.gelu = gelu_module

    def forward(self, x):
        return self.gelu.gelu_cuda(x.cuda().contiguous())


def get_inputs():
    return [torch.rand(8192, 8192)]


def get_init_inputs():
    return []

